inserted_invoices as (
  insert into invoices (client_id, invoice_number, amount_cents, status, issued_date, due_date, conversion_rate, payout_type, paid_at)
  select d.client_id, d.invoice_number, d.amount_cents, 'paid', d.issued_date, d.issued_date, d.conversion_rate, 'normal', d.paid_at
  from invoice_data d
  where not exists (
    select 1 from invoices i where i.invoice_number = d.invoice_number and i.client_id = d.client_id
  )
  returning id, invoice_number, client_id
),
updated_existing as (
  update invoices i
  set status = 'paid', paid_at = d.paid_at, conversion_rate = coalesce(i.conversion_rate, d.conversion_rate)
  from invoice_data d
  where i.invoice_number = d.invoice_number and i.client_id = d.client_id and i.status <> 'paid'
  returning i.id, i.invoice_number, i.client_id
)
insert into payments (client_id, invoice_id, amount_cents, payment_date, method)
select p.client_id, i.id, p.amount_cents, p.payment_date, 'Bank transfer (Skydo)'
from payment_data p
join invoices i on i.invoice_number = p.invoice_number and i.client_id = p.client_id
where not exists (
  select 1 from payments pay
  where pay.invoice_id = i.id and pay.amount_cents = p.amount_cents and pay.payment_date = p.payment_date
);
